    #include <iostream>
#include <vector>
#include <string>
using namespace std;

class Manacher {
public:
    vector<int> p;
    string ms;

    Manacher(string &s) {

        // build modified string with sentinels and separators
        ms = "@";
        for (char c : s) ms += "#" + string(1, c);
        ms += "#$";
        runManacher();
    }

    void runManacher() {
        int n = ms.size();
        p.assign(n, 0);

        int left = 0, right = 0;

        for (int i = 1; i < n - 1; ++i) {
            int mirror = left + right - i;

            // initialize radius using mirror or boundary
            if (i < right) p[i] = min(right - i, p[mirror]);

            // expand around i
            while (ms[i + p[i] + 1] == ms[i - p[i] - 1])
